@@ -0,0 +1,64 @@
+package download_test
+
+import (
+"os"
+"path/filepath"
+"testing"
+
+"github.com/cli/cli/v2/pkg/cmd/run/download"
+"github.com/cli/cli/v2/pkg/iostreams"
+"github.com/stretchr/testify/assert"
+)
+
+func Test_runDownload_artifact_path_traversal(t *testing.T) {
+safeDir := t.TempDir()
+evilDir := filepath.Join(t.TempDir(), "evil_dir")
+if err := os.Mkdir(evilDir, 0755); err != nil {
+t.Fatal(err)
+}
+
+opts := &download.DownloadOptions{
+IO:             iostreams.System(),
+Platform:       &mockPlatform{},
+DestinationDir: evilDir,
+Names:          []string{".."},
+}
+
+// This is the file that should not be created
+rogueFile := filepath.Join(safeDir, "safe_file")
+
+// The mocked download function will create the rogue file
+mockDownload := func(url string, dir string) error {
+if err := os.WriteFile(filepath.Join(dir, "safe_file"), []byte("evil"), 0644); err != nil {
+return err
+}
+return nil
+}
+opts.Platform.(*mockPlatform).download = mockDownload
+
+// Run the download command
+err := download.RunDownload(opts)
+if err == nil {
+t.Fatal("Expected an error but got none")
+}
+
+// Check if the rogue file was created
+if _, err := os.Stat(rogueFile); !os.IsNotExist(err) {
+t.Errorf("Rogue file was created at %s", rogueFile)
+}
+
+assert.Contains(t, err.Error(), "invalid artifact name: ..")
+}
+
+type mockPlatform struct {
+artifacts []download.shared.Artifact
+download  func(string, string) error
+}
+
+func (m *mockPlatform) List(runID string) ([]download.shared.Artifact, error) {
+return m.artifacts, nil
+}
+
+func (m *mockPlatform) Download(url string, dir string) error {
+return m.download(url, dir)
+}

