+package file
+
+import (
+"archive/tar"
+"bytes"
+"io/ioutil"
+"os"
+"path/filepath"
+"testing"
+
+"github.com/stretchr/testify/assert"
+)
+
+func TestUntarToDirectory(t *testing.T) {
+tmpDir, err := ioutil.TempDir("", "stereoscope-untar-test-")
+assert.NoError(t, err)
+defer os.RemoveAll(tmpDir)
+
+// Create a tar archive with a path traversal attempt
+var buf bytes.Buffer
+tw := tar.NewWriter(&buf)
+hdr := &tar.Header{
+Name:     "../../../../tmp/pwned",
+Mode:     0600,
+Size:     int64(len("pwned")),
+Typeflag: tar.TypeReg,
+}
+err = tw.WriteHeader(hdr)
+assert.NoError(t, err)
+_, err = tw.Write([]byte("pwned"))
+assert.NoError(t, err)
+err = tw.Close()
+assert.NoError(t, err)
+
+// Attempt to untar the archive
+err = UntarToDirectory(&buf, tmpDir)
+assert.Error(t, err)
+
+// Check that the malicious file was not created
+_, err = os.Stat(filepath.Join(tmpDir, "../../../../tmp/pwned"))
+assert.True(t, os.IsNotExist(err))
+}
