+// IsJoiningWithin returns true if the result of joining a base path and a joining path a path that is within the base path.
+//
+// It is a wrapper around `filepath.Join` that returns an error case if the joined path would be outside of the base path.
+func IsJoiningWithin(base, joining string) (string, bool) {
+joined := filepath.Join(base, joining)
+rel, err := filepath.Rel(base, joined)
+if err != nil {
+return "", false
+}
+// Note that we don't use `filepath.IsAbs` here because it returns false on Windows for paths like `oo`.
+if rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
+return "", false
+}
+return joined, true
+}
