+return
+}
+if !sp.IsAllowed(userPolicy) {
+writeErrorResponseJSON(ctx, w, errorCodes.ToAPIErr(ErrAccessDenied), r.URL)
+return
+}
+}
+}
+}
+        opts := updateServiceAccountOpts{
